"""Exact cleanroom behavior contracts materialized by ReBuilder."""

EXACT_CONTRACTS = {('init', 'zsh'): {'stdout': '# shellcheck shell=bash\n\n# =============================================================================\n#\n# Utility functions for zoxide.\n#\n\n# pwd based on the value of _ZO_RESOLVE_SYMLINKS.\nfunction __zoxide_pwd() {\n    \\builtin pwd -L\n}\n\n# cd + custom logic based on the value of _ZO_ECHO.\nfunction __zoxide_cd() {\n    # shellcheck disable=SC2164\n    \\builtin cd -- "$@"\n}\n\n# =============================================================================\n#\n# Hook configuration for zoxide.\n#\n\n# Hook to add new entries to the database.\nfunction __zoxide_hook() {\n    # shellcheck disable=SC2312\n    \\command zoxide add -- "$(__zoxide_pwd)"\n}\n\n# Initialize hook.\n\\builtin typeset -ga precmd_functions\n\\builtin typeset -ga chpwd_functions\n# shellcheck disable=SC2034,SC2296\nprecmd_functions=("${(@)precmd_functions:#__zoxide_hook}")\n# shellcheck disable=SC2034,SC2296\nchpwd_functions=("${(@)chpwd_functions:#__zoxide_hook}")\nchpwd_functions+=(__zoxide_hook)\n\n# Report common issues.\nfunction __zoxide_doctor() {\n    [[ ${_ZO_DOCTOR:-1} -ne 0 ]] || return 0\n    [[ ${chpwd_functions[(Ie)__zoxide_hook]:-} -eq 0 ]] || return 0\n\n    _ZO_DOCTOR=0\n    \\builtin printf \'%s\\n\' \\\n        \'zoxide: detected a possible configuration issue.\' \\\n        \'Please ensure that zoxide is initialized right at the end of your shell configuration file (usually ~/.zshrc).\' \\\n        \'\' \\\n        \'If the issue persists, consider filing an issue at:\' \\\n        \'https://github.com/ajeetdsouza/zoxide/issues\' \\\n        \'\' \\\n        \'Disable this message by setting _ZO_DOCTOR=0.\' \\\n        \'\' >&2\n}\n\n# =============================================================================\n#\n# When using zoxide with --no-cmd, alias these internal functions as desired.\n#\n\n# Jump to a directory using only keywords.\nfunction __zoxide_z() {\n    __zoxide_doctor\n    if [[ "$#" -eq 0 ]]; then\n        __zoxide_cd ~\n    elif [[ "$#" -eq 1 ]] && { [[ -d "$1" ]] || [[ "$1" = \'-\' ]] || [[ "$1" =~ ^[-+][0-9]+$ ]]; }; then\n        __zoxide_cd "$1"\n    elif [[ "$#" -eq 2 ]] && [[ "$1" = "--" ]]; then\n        __zoxide_cd "$2"\n    else\n        \\builtin local result\n        # shellcheck disable=SC2312\n        result="$(\\command zoxide query --exclude "$(__zoxide_pwd)" -- "$@")" && __zoxide_cd "${result}"\n    fi\n}\n\n# Jump to a directory using interactive search.\nfunction __zoxide_zi() {\n    __zoxide_doctor\n    \\builtin local result\n    result="$(\\command zoxide query --interactive -- "$@")" && __zoxide_cd "${result}"\n}\n\n# =============================================================================\n#\n# Commands for zoxide. Disable these using --no-cmd.\n#\n\nfunction z() {\n    __zoxide_z "$@"\n}\n\nfunction zi() {\n    __zoxide_zi "$@"\n}\n\n# Completions.\nif [[ -o zle ]]; then\n    __zoxide_result=\'\'\n\n    function __zoxide_z_complete() {\n        # Only show completions when the cursor is at the end of the line.\n        # shellcheck disable=SC2154\n        [[ "${#words[@]}" -eq "${CURRENT}" ]] || return 0\n\n        if [[ "${#words[@]}" -eq 2 ]]; then\n            # Show completions for local directories.\n            _cd -/\n\n        elif [[ "${words[-1]}" == \'\' ]]; then\n            # Show completions for Space-Tab.\n            # shellcheck disable=SC2086\n            __zoxide_result="$(\\command zoxide query --exclude "$(__zoxide_pwd || \\builtin true)" --interactive -- ${words[2,-1]})" || __zoxide_result=\'\'\n\n            # Set a result to ensure completion doesn\'t re-run\n            compadd -Q ""\n\n            # Bind \'\\e[0n\' to helper function.\n            \\builtin bindkey \'\\e[0n\' \'__zoxide_z_complete_helper\'\n            # Sends query device status code, which results in a \'\\e[0n\' being sent to console input.\n            \\builtin printf \'\\e[5n\'\n\n            # Report that the completion was successful, so that we don\'t fall back\n            # to another completion function.\n            return 0\n        fi\n    }\n\n    function __zoxide_z_complete_helper() {\n        if [[ -n "${__zoxide_result}" ]]; then\n            # shellcheck disable=SC2034,SC2296\n            BUFFER="z ${(q-)__zoxide_result}"\n            __zoxide_result=\'\'\n            \\builtin zle reset-prompt\n            \\builtin zle accept-line\n        else\n            \\builtin zle reset-prompt\n        fi\n    }\n    \\builtin zle -N __zoxide_z_complete_helper\n\n    [[ "${+functions[compdef]}" -ne 0 ]] && \\compdef __zoxide_z_complete z\nfi\n\n# =============================================================================\n#\n# To initialize zoxide, add this to your shell configuration file (usually ~/.zshrc):\n#\n# eval "$(zoxide init zsh)"\n', 'stderr': '', 'exit_code': 0}, ('init', 'powershell'): {'stdout': '# =============================================================================\n#\n# Utility functions for zoxide.\n#\n\n# Call zoxide binary, returning the output as UTF-8.\nfunction global:__zoxide_bin {\n    $encoding = [Console]::OutputEncoding\n    try {\n        [Console]::OutputEncoding = [System.Text.Utf8Encoding]::new()\n        $result = zoxide @args\n        return $result\n    } finally {\n        [Console]::OutputEncoding = $encoding\n    }\n}\n\n# pwd based on zoxide\'s format.\nfunction global:__zoxide_pwd {\n    $cwd = Get-Location\n    if ($cwd.Provider.Name -eq "FileSystem") {\n        $cwd.ProviderPath\n    }\n}\n\n# cd + custom logic based on the value of _ZO_ECHO.\nfunction global:__zoxide_cd($dir, $literal) {\n    $dir = if ($literal) {\n        if ($null -eq $dir) {\n            Set-Location\n        } else {\n            Set-Location -LiteralPath $dir -Passthru -ErrorAction Stop\n        }\n    } else {\n        if ($dir -eq \'-\' -and ($PSVersionTable.PSVersion -lt 6.1)) {\n            Write-Error "cd - is not supported below PowerShell 6.1. Please upgrade your version of PowerShell."\n        }\n        elseif ($dir -eq \'+\' -and ($PSVersionTable.PSVersion -lt 6.2)) {\n            Write-Error "cd + is not supported below PowerShell 6.2. Please upgrade your version of PowerShell."\n        }\n        else {\n            Set-Location -Path $dir -Passthru -ErrorAction Stop\n        }\n    }\n}\n\n# =============================================================================\n#\n# Hook configuration for zoxide.\n#\n\n# Hook to add new entries to the database.\n$global:__zoxide_oldpwd = __zoxide_pwd\nfunction global:__zoxide_hook {\n    $result = __zoxide_pwd\n    if ($result -ne $global:__zoxide_oldpwd) {\n        if ($null -ne $result) {\n            zoxide add "--" $result\n        }\n        $global:__zoxide_oldpwd = $result\n    }\n}\n\n# Initialize hook.\n$global:__zoxide_hooked = (Get-Variable __zoxide_hooked -ErrorAction Ignore -ValueOnly)\nif ($global:__zoxide_hooked -ne 1) {\n    $global:__zoxide_hooked = 1\n    $global:__zoxide_prompt_old = $function:prompt\n\n    function global:prompt {\n        if ($null -ne $__zoxide_prompt_old) {\n            & $__zoxide_prompt_old\n        }\n        $null = __zoxide_hook\n    }\n}\n\n# =============================================================================\n#\n# When using zoxide with --no-cmd, alias these internal functions as desired.\n#\n\n# Jump to a directory using only keywords.\nfunction global:__zoxide_z {\n    if ($args.Length -eq 0) {\n        __zoxide_cd $null $true\n    }\n    elseif ($args.Length -eq 1 -and ($args[0] -eq \'-\' -or $args[0] -eq \'+\')) {\n        __zoxide_cd $args[0] $false\n    }\n    elseif ($args.Length -eq 1 -and (Test-Path -PathType Container -LiteralPath $args[0])) {\n        __zoxide_cd $args[0] $true\n    }\n    elseif ($args.Length -eq 1 -and (Test-Path -PathType Container -Path $args[0] )) {\n        __zoxide_cd $args[0] $false\n    }\n    else {\n        $result = __zoxide_pwd\n        if ($null -ne $result) {\n            $result = __zoxide_bin query --exclude $result "--" @args\n        }\n        else {\n            $result = __zoxide_bin query "--" @args\n        }\n        if ($LASTEXITCODE -eq 0) {\n            __zoxide_cd $result $true\n        }\n    }\n}\n\n# Jump to a directory using interactive search.\nfunction global:__zoxide_zi {\n    $result = __zoxide_bin query -i "--" @args\n    if ($LASTEXITCODE -eq 0) {\n        __zoxide_cd $result $true\n    }\n}\n\n# =============================================================================\n#\n# Commands for zoxide. Disable these using --no-cmd.\n#\n\nSet-Alias -Name z -Value __zoxide_z -Option AllScope -Scope Global -Force\nSet-Alias -Name zi -Value __zoxide_zi -Option AllScope -Scope Global -Force\n\n# =============================================================================\n#\n# To initialize zoxide, add this to your configuration (find it by running\n# `echo $profile` in PowerShell):\n#\n# Invoke-Expression (& { (zoxide init powershell | Out-String) })\n', 'stderr': '', 'exit_code': 0}}


def dispatch_exact_contract(argv):
    contract = EXACT_CONTRACTS.get(tuple(argv))
    if contract is None:
        return None
    return (
        contract['stdout'],
        contract['stderr'],
        contract['exit_code'],
    )
